import 'dart:typed_data';
import 'package:dio/dio.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_dotenv/flutter_dotenv.dart';import 'package:mobile_dikasa/core/network/api_client.dart';import 'package:mobile_dikasa/data/services/cash_movement_service.dart';import 'package:mobile_dikasa/data/models/cash_movement.dart';
void main(){setUp(()=>dotenv.loadFromString(envString:'API_BASE_URL=http://localhost/dikasa/v1\nUSE_MOCK_API=false'));
 test('same pending command recreates identical multipart and treats lost reply as uncertain',()async{final c=ApiClient();var calls=0;c.dio.interceptors.add(InterceptorsWrapper(onRequest:(o,h){calls++;final d=o.data as FormData;expect(Map.fromEntries(d.fields)['request_id'],'request');expect(Map.fromEntries(d.fields)['amount'],'123');expect(d.files.single.key,'proof');h.reject(DioException(requestOptions:o,type:DioExceptionType.receiveTimeout));}));final s=CashMovementService(c);final p=PendingCashMovement(sessionId:'session',requestId:'request',kind:'out',name:'Bank',amount:123,reason:'Deposit',proofBytes:Uint8List.fromList([1,2]),proofName:'p.png');await expectLater(s.create('session',p),throwsA(isA<CashMovementUncertainException>()));await expectLater(s.create('session',p),throwsA(isA<CashMovementUncertainException>()));expect(calls,2);});
}
